'use client';

import { TimedCards, TimedCardData } from '@/components/core/timed-cards';

const DATA: TimedCardData[] = [
  {
    place: 'Switzerland Alps',
    title: 'SAINT',
    title2: 'ANTONIEN',
    description:
      "Tucked away in the Switzerland Alps, Saint Antönien offers an idyllic retreat for those seeking tranquility and adventure alike. It's a hidden gem for backcountry skiing in winter and boasts lush trails for hiking and mountain biking during the warmer months.",
    image: 'https://images.unsplash.com/photo-1531366936337-7c912a4589a7',
  },
  {
    place: 'Japan Alps',
    title: 'NAGANO',
    title2: 'PREFECTURE',
    description:
      "Nagano Prefecture, set within the majestic Japan Alps, is a cultural treasure trove with its historic shrines and temples, particularly the famous Zenkō-ji. The region is also a hotspot for skiing and snowboarding, offering some of the country's best powder.",
    image: 'https://images.unsplash.com/photo-1578339031317-575510de3e15',
  },
  {
    place: 'Sahara Desert - Morocco',
    title: 'MARRAKECH',
    title2: 'MERZOUGA',
    description:
      'The journey from the vibrant souks and palaces of Marrakech to the tranquil, starlit sands of Merzouga showcases the diverse splendor of Morocco. Camel treks and desert camps offer an unforgettable immersion into the nomadic way of life.',
    image: 'https://images.unsplash.com/photo-1534430480872-3498386e7856',
  },
  {
    place: 'Sierra Nevada - USA',
    title: 'YOSEMITE',
    title2: 'NATIONAL PARK',
    description:
      'Yosemite National Park is a showcase of the American wilderness, revered for its towering granite monoliths, ancient giant sequoias, and thundering waterfalls. The park offers year-round recreational activities, from rock climbing to serene valley walks.',
    image: 'https://images.unsplash.com/photo-1426604966848-d7adac402bff',
  },
  {
    place: 'Tarifa - Spain',
    title: 'LOS LANCES',
    title2: 'BEACH',
    description:
      "Los Lances Beach in Tarifa is a coastal paradise known for its consistent winds, making it a world-renowned spot for kitesurfing and windsurfing. The beach's long, sandy shores provide ample space for relaxation and sunbathing, with a vibrant atmosphere of beach bars and cafes.",
    image: 'https://images.unsplash.com/photo-1517400508447-f8dd518b86db',
  },
  {
    place: 'Cappadocia - Turkey',
    title: 'GÖREME',
    title2: 'VALLEY',
    description:
      'Göreme Valley in Cappadocia is a historical marvel set against a unique geological backdrop, where centuries of wind and water have sculpted the landscape into whimsical formations. The valley is also famous for its open-air museums, underground cities, and the enchanting experience of hot air ballooning.',
    image: 'https://images.unsplash.com/photo-1605652514652-3269a848a602',
  },
];

export function TimedCardsBasic() {
  return (
    <div className='h-[600px] w-full overflow-hidden rounded-xl border'>
      <TimedCards data={DATA} />
    </div>
  );
}

'use client';

import React, { useEffect, useRef, useState } from 'react';
import gsap from 'gsap';
import { cn } from '@/lib/utils';
import { ChevronLeft, ChevronRight, Bookmark } from 'lucide-react';
import './timed-cards.css';

export interface TimedCardData {
  place: string;
  title: string;
  title2: string;
  description: string;
  image: string;
}

export interface TimedCardsProps extends React.HTMLAttributes<HTMLDivElement> {
  data: TimedCardData[];
}

export const TimedCards = React.forwardRef<HTMLDivElement, TimedCardsProps>(
  ({ data, className, ...props }, ref) => {
    const containerRef = useRef<HTMLDivElement | null>(null);
    const [isLoaded, setIsLoaded] = useState(false);

    useEffect(() => {
      if (!data || data.length === 0) return;
      Promise.all(
        data.map((item) => {
          return new Promise((resolve, reject) => {
            const img = new Image();
            img.onload = resolve;
            img.onerror = reject;
            img.src = item.image;
          });
        })
      )
        .then(() => setIsLoaded(true))
        .catch(console.error);
    }, [data]);

    useEffect(() => {
      if (!isLoaded || !containerRef.current || data.length === 0) return;

      const ctx = gsap.context(() => {
        let order = data.map((_, i) => i);
        let detailsEven = true;

        let offsetTop = 200;
        let offsetLeft = 700;
        let cardWidth = 200;
        let cardHeight = 300;
        const gap = 40;
        const numberSize = 50;
        const ease = 'sine.inOut';

        function getCard(index: number) {
          return `.card-${index}`;
        }
        function getCardContent(index: number) {
          return `.card-content-${index}`;
        }
        function getSliderItem(index: number) {
          return `.slide-item-${index}`;
        }

        function animate(target: string, duration: number, properties: any) {
          return new Promise<void>((resolve) => {
            gsap.to(target, {
              ...properties,
              duration: duration,
              onComplete: resolve,
            });
          });
        }

        function init() {
          const [active, ...rest] = order;
          const detailsActive = detailsEven ? '.details-even' : '.details-odd';
          const detailsInactive = detailsEven
            ? '.details-odd'
            : '.details-even';

          const height = containerRef.current!.clientHeight;
          const width = containerRef.current!.clientWidth;

          offsetTop = height - 430;
          offsetLeft = width - 830;

          if (offsetLeft < 400) offsetLeft = width - cardWidth - gap * 2;
          if (offsetTop < 200) offsetTop = height - cardHeight - gap;

          gsap.set('.timed-cards-pagination', {
            top: offsetTop + 330,
            left: offsetLeft,
            y: 200,
            opacity: 0,
            zIndex: 60,
          });

          gsap.set(getCard(active), {
            x: 0,
            y: 0,
            width: width,
            height: height,
          });
          gsap.set(getCardContent(active), { x: 0, y: 0, opacity: 0 });
          gsap.set(detailsActive, { opacity: 0, zIndex: 22, x: -200 });
          gsap.set(detailsInactive, { opacity: 0, zIndex: 12 });
          gsap.set(`${detailsInactive} .text`, { y: 100 });
          gsap.set(`${detailsInactive} .title-1`, { y: 100 });
          gsap.set(`${detailsInactive} .title-2`, { y: 100 });
          gsap.set(`${detailsInactive} .desc`, { y: 50 });
          gsap.set(`${detailsInactive} .cta`, { y: 60 });

          gsap.set('.progress-sub-foreground', {
            width: 500 * (1 / order.length) * (active + 1),
          });

          rest.forEach((i, index) => {
            gsap.set(getCard(i), {
              x: offsetLeft + 400 + index * (cardWidth + gap),
              y: offsetTop,
              width: cardWidth,
              height: cardHeight,
              zIndex: 30,
              borderRadius: 10,
            });
            gsap.set(getCardContent(i), {
              x: offsetLeft + 400 + index * (cardWidth + gap),
              zIndex: 40,
              y: offsetTop + cardHeight - 100,
            });
            gsap.set(getSliderItem(i), { x: (index + 1) * numberSize });
          });

          gsap.set('.timed-cards-indicator', { x: -width });

          const startDelay = 0.6;

          gsap.to('.timed-cards-cover', {
            x: width + 400,
            delay: 0.5,
            ease,
            onComplete: () => {
              setTimeout(() => {
                loop();
              }, 500);
            },
          });
          rest.forEach((i, index) => {
            gsap.to(getCard(i), {
              x: offsetLeft + index * (cardWidth + gap),
              zIndex: 30,
              delay: startDelay + 0.05 * index,
              ease,
            });
            gsap.to(getCardContent(i), {
              x: offsetLeft + index * (cardWidth + gap),
              zIndex: 40,
              delay: startDelay + 0.05 * index,
              ease,
            });
          });
          gsap.to('.timed-cards-pagination', {
            y: 0,
            opacity: 1,
            ease,
            delay: startDelay,
          });
          gsap.to(detailsActive, { opacity: 1, x: 0, ease, delay: startDelay });
        }

        let isAnimating = false;

        function step() {
          return new Promise<void>((resolve) => {
            order.push(order.shift()!);
            detailsEven = !detailsEven;

            const detailsActive = detailsEven
              ? '.details-even'
              : '.details-odd';
            const detailsInactive = detailsEven
              ? '.details-odd'
              : '.details-even';

            const activeNodePlace = document.querySelector(
              `${detailsActive} .place-box .text`
            );
            const activeNodeTitle1 = document.querySelector(
              `${detailsActive} .title-1`
            );
            const activeNodeTitle2 = document.querySelector(
              `${detailsActive} .title-2`
            );
            const activeNodeDesc = document.querySelector(
              `${detailsActive} .desc`
            );

            if (activeNodePlace)
              activeNodePlace.textContent = data[order[0]].place;
            if (activeNodeTitle1)
              activeNodeTitle1.textContent = data[order[0]].title;
            if (activeNodeTitle2)
              activeNodeTitle2.textContent = data[order[0]].title2;
            if (activeNodeDesc)
              activeNodeDesc.textContent = data[order[0]].description;

            gsap.set(detailsActive, { zIndex: 22 });
            gsap.to(detailsActive, { opacity: 1, delay: 0.4, ease });
            gsap.to(`${detailsActive} .text`, {
              y: 0,
              delay: 0.1,
              duration: 0.7,
              ease,
            });
            gsap.to(`${detailsActive} .title-1`, {
              y: 0,
              delay: 0.15,
              duration: 0.7,
              ease,
            });
            gsap.to(`${detailsActive} .title-2`, {
              y: 0,
              delay: 0.15,
              duration: 0.7,
              ease,
            });
            gsap.to(`${detailsActive} .desc`, {
              y: 0,
              delay: 0.3,
              duration: 0.4,
              ease,
            });
            gsap.to(`${detailsActive} .cta`, {
              y: 0,
              delay: 0.35,
              duration: 0.4,
              onComplete: resolve,
              ease,
            });
            gsap.set(detailsInactive, { zIndex: 12 });

            const [active, ...rest] = order;
            const prv = rest[rest.length - 1];

            gsap.set(getCard(prv), { zIndex: 10 });
            gsap.set(getCard(active), { zIndex: 20 });
            gsap.to(getCard(prv), { scale: 1.5, ease });

            gsap.to(getCardContent(active), {
              y: offsetTop + cardHeight - 10,
              opacity: 0,
              duration: 0.3,
              ease,
            });
            gsap.to(getSliderItem(active), { x: 0, ease });
            gsap.to(getSliderItem(prv), { x: -numberSize, ease });
            gsap.to('.progress-sub-foreground', {
              width: 500 * (1 / order.length) * (active + 1),
              ease,
            });

            gsap.to(getCard(active), {
              x: 0,
              y: 0,
              ease,
              width: containerRef.current!.clientWidth,
              height: containerRef.current!.clientHeight,
              borderRadius: 0,
              onComplete: () => {
                const xNew = offsetLeft + (rest.length - 1) * (cardWidth + gap);
                gsap.set(getCard(prv), {
                  x: xNew,
                  y: offsetTop,
                  width: cardWidth,
                  height: cardHeight,
                  zIndex: 30,
                  borderRadius: 10,
                  scale: 1,
                });

                gsap.set(getCardContent(prv), {
                  x: xNew,
                  y: offsetTop + cardHeight - 100,
                  opacity: 1,
                  zIndex: 40,
                });
                gsap.set(getSliderItem(prv), { x: rest.length * numberSize });

                gsap.set(detailsInactive, { opacity: 0 });
                gsap.set(`${detailsInactive} .text`, { y: 100 });
                gsap.set(`${detailsInactive} .title-1`, { y: 100 });
                gsap.set(`${detailsInactive} .title-2`, { y: 100 });
                gsap.set(`${detailsInactive} .desc`, { y: 50 });
                gsap.set(`${detailsInactive} .cta`, { y: 60 });
              },
            });

            rest.forEach((i, index) => {
              if (i !== prv) {
                const xNew = offsetLeft + index * (cardWidth + gap);
                gsap.set(getCard(i), { zIndex: 30 });
                gsap.to(getCard(i), {
                  x: xNew,
                  y: offsetTop,
                  width: cardWidth,
                  height: cardHeight,
                  ease,
                  delay: 0.1 * (index + 1),
                });

                gsap.to(getCardContent(i), {
                  x: xNew,
                  y: offsetTop + cardHeight - 100,
                  opacity: 1,
                  zIndex: 40,
                  ease,
                  delay: 0.1 * (index + 1),
                });
                gsap.to(getSliderItem(i), {
                  x: (index + 1) * numberSize,
                  ease,
                });
              }
            });
          });
        }

        let loopTimeout: ReturnType<typeof setTimeout>;
        let isLooping = true;

        async function loop() {
          if (!isLooping) return;
          const width = containerRef.current!.clientWidth;
          await animate('.timed-cards-indicator', 2, { x: 0 });
          await animate('.timed-cards-indicator', 0.8, {
            x: width,
            delay: 0.3,
          });
          gsap.set('.timed-cards-indicator', { x: -width });
          await step();
          loopTimeout = setTimeout(loop, 10);
        }

        init();

        return () => {
          isLooping = false;
          clearTimeout(loopTimeout);
        };
      }, containerRef);

      return () => ctx.revert();
    }, [isLoaded, data]);

    if (!data || data.length === 0) return null;

    return (
      <div
        ref={(node) => {
          if (typeof ref === 'function') ref(node);
          else if (ref)
            (ref as React.MutableRefObject<HTMLDivElement | null>).current =
              node;
          containerRef.current = node;
        }}
        className={cn('timed-cards-root', className)}
        {...props}
      >
        <div className='timed-cards-indicator'></div>

        {data.map((item, index) => (
          <React.Fragment key={index}>
            <div
              className={`timed-cards-card card-${index}`}
              style={{ backgroundImage: `url(${item.image})` }}
            ></div>
            <div className={`timed-cards-card-content card-content-${index}`}>
              <div className='timed-cards-content-start'></div>
              <div className='timed-cards-content-place'>{item.place}</div>
              <div className='timed-cards-content-title-1'>{item.title}</div>
              <div className='timed-cards-content-title-2'>{item.title2}</div>
            </div>
          </React.Fragment>
        ))}

        <div className='timed-cards-details details-even'>
          <div className='place-box'>
            <div className='text'>{data[0]?.place}</div>
          </div>
          <div className='title-box-1'>
            <div className='title-1'>{data[0]?.title}</div>
          </div>
          <div className='title-box-2'>
            <div className='title-2'>{data[0]?.title2}</div>
          </div>
          <div className='desc'>{data[0]?.description}</div>
          <div className='cta'>
            <button className='bookmark'>
              <Bookmark className='h-4 w-4 fill-white text-white' />
            </button>
            <button className='discover'>Discover Location</button>
          </div>
        </div>

        <div className='timed-cards-details details-odd'>
          <div className='place-box'>
            <div className='text'>{data[0]?.place}</div>
          </div>
          <div className='title-box-1'>
            <div className='title-1'>{data[0]?.title}</div>
          </div>
          <div className='title-box-2'>
            <div className='title-2'>{data[0]?.title2}</div>
          </div>
          <div className='desc'>{data[0]?.description}</div>
          <div className='cta'>
            <button className='bookmark'>
              <Bookmark className='h-4 w-4 fill-white text-white' />
            </button>
            <button className='discover'>Discover Location</button>
          </div>
        </div>

        <div className='timed-cards-pagination'>
          <div className='arrow arrow-left'>
            <ChevronLeft className='h-6 w-6' />
          </div>
          <div className='arrow arrow-right'>
            <ChevronRight className='h-6 w-6' />
          </div>
          <div className='progress-sub-container'>
            <div className='progress-sub-background'>
              <div className='progress-sub-foreground'></div>
            </div>
          </div>
          <div className='slide-numbers'>
            {data.map((_, index) => (
              <div className={`item slide-item-${index}`} key={index}>
                {index + 1}
              </div>
            ))}
          </div>
        </div>

        <div className='timed-cards-cover'></div>
      </div>
    );
  }
);

TimedCards.displayName = 'TimedCards';
